import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

l2_norm_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

__global__ void l2_normalize_kernel(const float* x, float* out, int dim) {
    extern __shared__ float sdata[];
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    int start = batch_idx * dim + tid;
    float sum_sq = 0.0f;

    // Strided access for coalesced memory reads
    for (int i = tid; i < dim; i += blockDim.x) {
        float val = x[batch_idx * dim + i];
        sum_sq += val * val;
    }

    sdata[tid] = sum_sq;
    __syncthreads();

    // Parallel reduction
    for (int s = blockDim.x/2; s>0; s>>=1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    float norm = sqrtf(sdata[0] + 1e-12f);  // Add epsilon for numerical stability

    // Write normalized values with strided access
    for (int i = tid; i < dim; i += blockDim.x) {
        out[batch_idx * dim + i] = x[batch_idx * dim + i] / norm;
    }
}

torch::Tensor l2_normalize_cuda(torch::Tensor x) {
    auto out = torch::empty_like(x);
    int batch_size = x.size(0);
    int dim = x.size(1);

    const int block_size = 256;
    int shared_mem = block_size * sizeof(float);

    l2_normalize_kernel<<<batch_size, block_size, shared_mem>>>(
        x.data_ptr<float>(), out.data_ptr<float>(), dim
    );

    return out;
}
"""

l2_norm_cpp = "torch::Tensor l2_normalize_cuda(torch::Tensor x);"

l2_norm_ext = load_inline(
    name='l2_norm_ext',
    cpp_sources=l2_norm_cpp,
    cuda_sources=l2_norm_source,
    functions=['l2_normalize_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.normalize = l2_norm_ext.l2_normalize_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.normalize(x)
